const cvText = String($json.text ?? $json.extractedText ?? '');

// EDIT THESE CRITERIA FOR YOUR JOB ROLE.
const job = {
  title: 'Full Stack Developer',
  requiredSkills: ['javascript', 'react', 'node.js', 'express', 'api', 'mongodb', 'git'],
  preferredSkills: ['python', 'django', 'postgresql', 'docker', 'testing'],
  minimumRequiredMatches: 4
};

const normalized = cvText.toLowerCase();
const findMatches = (skills) => skills.filter(skill => normalized.includes(skill.toLowerCase()));
const requiredMatches = findMatches(job.requiredSkills);
const preferredMatches = findMatches(job.preferredSkills);
const missingRequiredSkills = job.requiredSkills.filter(skill => !requiredMatches.includes(skill));
const score = Math.round(((requiredMatches.length / Math.max(job.requiredSkills.length, 1)) * 80) + ((preferredMatches.length / Math.max(job.preferredSkills.length, 1)) * 20));
let preliminaryCategory = 'Needs manual review';
if (requiredMatches.length >= job.minimumRequiredMatches) preliminaryCategory = 'Potential match - review CV';
else preliminaryCategory = 'Insufficient keyword evidence - manual review';

return {
  json: {
    jobTitle: job.title,
    screeningMethod: 'Keyword matching only; not an employment decision',
    scoreOutOf100: score,
    preliminaryCategory,
    matchedRequiredSkills: requiredMatches,
    matchedPreferredSkills: preferredMatches,
    missingRequiredSkills,
    extractedTextPreview: cvText.slice(0, 1200),
    note: 'Verify skills and experience manually. Keyword absence does not prove a candidate lacks a skill.'
  }
};
